INSERT INTO `recipes` VALUES (1,'Spaghetti Carbonara','Spaghetti (200g), Eggs (2), Pancetta (100g), Parmesan Cheese (50g), Black Pepper (1 tsp), Salt (to taste)','1. Boil spaghetti until al dente.\n2. Cook pancetta until crispy.\n3. Whisk eggs with parmesan and black pepper.\n4. Mix with spaghetti (off heat) to create a creamy sauce.\n5. Add pancetta and serve.',20,'Medium','Italian','https://www.youtube.com/watch?v=3AAdKl1UYZs'),(2,'Chicken Biryani','Chicken (500g), Basmati Rice (2 cups), Yogurt (1/2 cup), Onion (2, sliced), Tomatoes (2, chopped), Ginger-Garlic Paste (1 tbsp), Biryani Spices','1. Marinate chicken with yogurt and spices.\r\n2. SautÃ© onions and tomatoes, add chicken.\r\n3. Cook until tender.\r\n4. Parboil rice, layer with chicken, and cook on low.',60,'Hard','Indian','https://www.youtube.com/watch?v=uygb9O-MDPw&ab_channel=YourFoodLab'),(3,'Vegetable Stir Fry','Broccoli (1 cup), Carrots (1/2 cup), Bell Peppers (1/2 cup), Soy Sauce (2 tbsp), Garlic (2 cloves, minced), Sesame Oil (1 tbsp)','1. Heat oil and sautÃ© garlic.\r\n2. Add carrots and cook.\r\n3. Add peppers and broccoli, then soy sauce.\r\n4. Stir-fry and serve hot.',15,'Easy','Chinese','https://www.youtube.com/watch?v=spDs_wzn8To&pp=ygUSVmVnZXRhYmxlIFN0aXIgRnJ5'),(4,'Beef Tacos','Ground Beef (200g), Tortillas (4), Lettuce (1/2 cup), Cheese (1/2 cup), Salsa (1/2 cup), Onion (1, chopped)','1. Cook beef until browned.\r\n2. Season and warm tortillas.\r\n3. Fill tortillas with beef, lettuce, cheese, and salsa.\r\n4. Serve.',25,'Easy','Mexican','https://www.youtube.com/watch?v=LVFyKPqqQ1g&pp=ygUKQmVlZiBUYWNvcw%3D%3D'),(5,'Mushroom Risotto','Arborio Rice (1 cup), Mushrooms (1 cup), Parmesan (1/2 cup), White Wine (1/2 cup), Chicken Broth (3 cups), Butter (2 tbsp), Onion (1, chopped)','1. SautÃ© onions and mushrooms.\r\n2. Add rice and toast briefly.\r\n3. Deglaze with wine and gradually add broth.\r\n4. Cook until creamy and mix in parmesan.',40,'Medium','Italian','https://www.youtube.com/watch?v=NKtR3KpS83w&pp=ygUQTXVzaHJvb20gUmlzb3R0bw%3D%3D'),(6,'Grilled Salmon','Salmon Fillet (1), Lemon Juice (1 tbsp), Olive Oil (1 tbsp), Garlic (1 clove, minced), Salt, Black Pepper','1. Marinate salmon with lemon juice, oil, garlic, salt, and pepper.\r\n2. Grill for 4-5 minutes per side.\r\n3. Serve with vegetables or rice.',15,'Easy','Seafood','https://www.youtube.com/watch?v=j7BkpjD-HZ0&pp=ygUOR3JpbGxlZCBTYWxtb24%3D'),(7,'Caesar Salad','Romaine Lettuce (2 cups), Croutons (1/2 cup), Parmesan Cheese (1/4 cup), Caesar Dressing (3 tbsp), Chicken Breast (1, grilled)','1. Chop romaine lettuce and mix with croutons.\r\n2. Slice grilled chicken and add.\r\n3. Toss with dressing and sprinkle parmesan.',10,'Easy','Salad','https://www.youtube.com/watch?v=IGlWE4AFQ5Q&ab_channel=Dabl'),(8,'Margherita Pizza','Pizza Dough (1), Tomato Sauce (1/2 cup), Mozzarella (1/2 cup), Fresh Basil (5 leaves), Olive Oil (1 tbsp)','1. Roll out dough and spread tomato sauce.\r\n2. Add mozzarella and basil.\r\n3. Bake at 220Â°C for 10-15 minutes.\r\n4. Drizzle with olive oil and serve.',25,'Medium','Italian','https://www.youtube.com/watch?v=vcfNpDtVqOw&pp=ygUQTWFyZ2hlcml0YSBQaXp6YQ%3D%3D'),(9,'Pancakes','Flour (1 cup), Milk (3/4 cup), Egg (1), Sugar (2 tbsp), Baking Powder (1 tsp), Butter (2 tbsp)','1. Mix flour, sugar, and baking powder.\r\n2. Whisk milk and egg, combine with dry ingredients.\r\n3. Heat butter and pour batter into a pan.\r\n4. Flip when bubbles form and cook until golden.',20,'Easy','Breakfast','https://www.youtube.com/watch?v=vkcHmpKxFwg&ab_channel=Epicurious'),(10,'Garlic Butter Shrimp','Shrimp (200g), Butter (2 tbsp), Garlic (3 cloves, minced), Lemon Juice (1 tbsp), Parsley (1 tbsp, chopped)','1. Melt butter and sautÃ© garlic.\r\n2. Add shrimp and cook for 3 minutes per side.\r\n3. Sprinkle with lemon juice and parsley.',15,'Easy','Seafood','https://www.youtube.com/watch?v=JS12i22tk7A&pp=ygUUR2FybGljIEJ1dHRlciBTaHJpbXA%3D'),(11,'Butter Chicken','Chicken (500g), Butter (3 tbsp), Tomatoes (2, pureed), Cream (1/2 cup), Garlic (2 cloves, minced), Garam Masala (1 tsp)','1. Cook chicken with butter and garlic.\r\n2. Add pureed tomatoes and simmer.\r\n3. Stir in cream and garam masala.\r\n4. Serve with naan or rice.',40,'Medium','Indian','https://www.youtube.com/watch?v=a03U45jFxOI&pp=ygUOQnV0dGVyIENoaWNrZW4%3D'),(12,'Greek Salad','Cucumber (1, chopped), Tomato (2, chopped), Red Onion (1/2, sliced), Feta Cheese (1/2 cup), Olives (1/4 cup), Olive Oil (2 tbsp)','1. Mix cucumber, tomato, onion, and olives.\r\n2. Add feta cheese and drizzle with olive oil.\r\n3. Toss well and serve.',10,'Easy','Salad','https://www.youtube.com/watch?v=T6-sIofa_4E&pp=ygULZ3JlZWsgc2FsYWQ%3D'),(13,'Beef Stroganoff','Beef (300g, sliced), Mushrooms (1 cup), Onion (1, chopped), Sour Cream (1/2 cup), Garlic (2 cloves, minced), Butter (2 tbsp)','1. SautÃ© onions and garlic.\r\n2. Add beef and cook until browned.\r\n3. Stir in mushrooms and sour cream.\r\n4. Serve with pasta or rice.',30,'Medium','Russian','https://www.youtube.com/watch?v=7r3dlmYUf4s&pp=ygUPQmVlZiBTdHJvZ2Fub2Zm'),(14,'Vegetable Curry','Potatoes (1 cup, diced), Carrots (1/2 cup, chopped), Green Beans (1/2 cup), Coconut Milk (1 cup), Curry Powder (1 tbsp)','1. SautÃ© vegetables with spices.\r\n2. Add coconut milk and simmer.\r\n3. Cook until vegetables are tender.\r\n4. Serve with rice.',35,'Medium','Indian','https://www.youtube.com/watch?v=sm_Pp_pjrnk&pp=ygUPVmVnZXRhYmxlIEN1cnJ5'),(15,'Shrimp Pad Thai','Rice Noodles (200g), Shrimp (200g), Eggs (2), Bean Sprouts (1 cup), Peanuts (1/4 cup), Soy Sauce (3 tbsp)','1. Cook noodles and set aside.\r\n2. Stir-fry shrimp, eggs, and vegetables.\r\n3. Mix with noodles and sauce.\r\n4. Serve with peanuts and lime.',25,'Medium','Thai','https://www.youtube.com/watch?v=GgVwdIwo7Ao&pp=ygUPU2hyaW1wIFBhZCBUaGFp'),(16,'Stuffed Bell Peppers','Bell Peppers (4), Ground Beef (300g), Rice (1 cup, cooked), Tomato Sauce (1/2 cup), Onion (1, chopped), Garlic (2 cloves, minced)','1. SautÃ© onions and garlic.\r\n2. Mix with beef, rice, and sauce.\r\n3. Stuff peppers and bake at 180Â°C for 30 minutes.',40,'Medium','American','https://www.youtube.com/watch?v=ektsiKFVqks&pp=ygUUU3R1ZmZlZCBCZWxsIFBlcHBlcnM%3D'),(17,'French Toast','Bread (4 slices), Eggs (2), Milk (1/2 cup), Cinnamon (1 tsp), Vanilla Extract (1 tsp), Butter (2 tbsp)','1. Whisk eggs, milk, cinnamon, and vanilla.\r\n2. Dip bread and cook on a buttered pan.\r\n3. Serve with syrup.',15,'Easy','Breakfast','https://www.youtube.com/watch?v=r1ZLSbQ0r0I&pp=ygUTZnJlbmNoIHRvYXN0IHJlY2lwZQ%3D%3D'),(18,'Tom Yum Soup','Shrimp (200g), Lemongrass (1 stalk), Kaffir Lime Leaves (2), Fish Sauce (2 tbsp), Chili Paste (1 tbsp), Mushrooms (1/2 cup)','1. Boil broth with lemongrass and lime leaves.\r\n2. Add shrimp, mushrooms, and seasoning.\r\n3. Simmer and serve.',25,'Medium','Thai','https://www.youtube.com/watch?v=TLl8n5WJJfI&pp=ygUMVG9tIFl1bSBTb3Vw'),(19,'Lemon Garlic Chicken','Chicken Breasts (2), Lemon Juice (2 tbsp), Garlic (2 cloves, minced), Olive Oil (1 tbsp), Black Pepper (1 tsp)','1. Marinate chicken with lemon, garlic, oil, and pepper.\r\n2. Grill for 5-7 minutes per side.\r\n3. Serve with vegetables.',20,'Easy','Healthy','https://www.youtube.com/watch?v=jvQKp7pVhF0&pp=ygUUTGVtb24gR2FybGljIENoaWNrZW4%3D'),(20,'BBQ Ribs','Pork Ribs (500g), BBQ Sauce (1/2 cup), Brown Sugar (2 tbsp), Garlic Powder (1 tsp), Paprika (1 tsp)','1. Rub ribs with spices.\r\n2. Bake at 160Â°C for 2 hours.\r\n3. Glaze with BBQ sauce and grill for 10 minutes.',140,'Hard','American','https://www.youtube.com/watch?v=vFLEDmNGRIw&pp=ygUIQkJRIFJpYnM%3D'),(21,'Miso Soup','Miso Paste (2 tbsp), Tofu (1/2 cup, cubed), Seaweed (1/4 cup), Green Onions (1, chopped), Dashi Broth (3 cups)','1. Heat dashi broth.\r\n2. Dissolve miso paste.\r\n3. Add tofu, seaweed, and onions.\r\n4. Serve hot.',15,'Easy','Japanese','https://www.youtube.com/watch?v=v4aXJsfl_Ss&pp=ygUJTWlzbyBTb3Vw'),(22,'Teriyaki Chicken','Chicken Thighs (2), Soy Sauce (3 tbsp), Honey (1 tbsp), Ginger (1 tsp, grated), Garlic (1 clove, minced)','1. Marinate chicken with sauce ingredients.\r\n2. Cook in a pan until caramelized.\r\n3. Serve with rice.',25,'Medium','Japanese','https://www.youtube.com/watch?v=jbRr01FqINo&pp=ygUQVGVyaXlha2kgQ2hpY2tlbg%3D%3D'),(23,'Egg Fried Rice','Rice (2 cups, cooked), Eggs (2), Soy Sauce (2 tbsp), Green Onions (1, chopped), Carrots (1/2 cup, diced)','1. Scramble eggs in a pan.\r\n2. Add rice, soy sauce, and vegetables.\r\n3. Stir-fry and serve.',15,'Easy','Chinese','https://www.youtube.com/watch?v=qH__o17xHls&pp=ygUORWdnIEZyaWVkIFJpY2U%3D'),(24,'Chicken Alfredo','Chicken Breast (1, sliced), Pasta (200g), Heavy Cream (1/2 cup), Parmesan Cheese (1/2 cup), Garlic (2 cloves, minced)','1. Cook pasta and set aside.\r\n2. SautÃ© garlic and chicken.\r\n3. Add cream and parmesan, mix with pasta.',30,'Medium','Italian','https://www.youtube.com/watch?v=LPPcNPdq_j4&pp=ygUPQ2hpY2tlbiBBbGZyZWRv'),(25,'Lentil Soup','Lentils (1 cup), Carrots (1/2 cup, diced), Onion (1, chopped), Garlic (2 cloves, minced), Cumin (1 tsp)','1. SautÃ© onion and garlic.\r\n2. Add lentils, vegetables, and water.\r\n3. Simmer for 30 minutes and serve.',35,'Easy','Vegan','https://www.youtube.com/watch?v=srnFEHpq184&pp=ygULTGVudGlsIFNvdXA%3D'),(26,'Pancakes','Flour (1 cup), Milk (1 cup), Egg (1), Sugar (1 tbsp), Baking Powder (1 tsp), Butter (2 tbsp)','1. Mix all ingredients into a smooth batter.\r\n2. Pour batter onto a heated pan.\r\n3. Flip when bubbles appear and cook until golden brown.\r\n4. Serve with syrup.',15,'Easy','Breakfast','https://www.youtube.com/watch?v=RaLzxZryEoA&pp=ygUIUGFuY2FrZXM%3D'),(27,'Chili Con Carne','Ground Beef (500g), Kidney Beans (1 cup), Tomato Sauce (1 cup), Onion (1, chopped), Chili Powder (1 tbsp)','1. SautÃ© onions and beef.\r\n2. Add beans, tomato sauce, and spices.\r\n3. Simmer for 30 minutes and serve.',40,'Medium','Mexican','https://www.youtube.com/watch?v=DCvIBlFmujY&pp=ygUPQ2hpbGkgQ29uIENhcm5l'),(28,'Caprese Salad','Tomatoes (2, sliced), Mozzarella (1 cup, sliced), Basil Leaves (1/4 cup), Olive Oil (2 tbsp), Balsamic Vinegar (1 tbsp)','1. Layer tomato and mozzarella slices.\r\n2. Sprinkle with basil leaves.\r\n3. Drizzle with olive oil and balsamic vinegar.',10,'Easy','Salad','https://www.youtube.com/watch?v=gOcfUgd4ekA&pp=ygUNQ2FwcmVzZSBTYWxhZA%3D%3D'),(29,'Chicken Biryani','Chicken (500g), Basmati Rice (2 cups), Yogurt (1/2 cup), Onion (1, fried), Garam Masala (1 tbsp), Saffron (1 pinch)','1. Marinate chicken with spices and yogurt.\r\n2. Cook rice separately.\r\n3. Layer chicken and rice, simmer for 20 minutes.\r\n4. Serve hot.',60,'Hard','Indian','https://www.youtube.com/watch?v=E_gWBBjYkjE&pp=ygUPQ2hpY2tlbiBCaXJ5YW5p'),(30,'Garlic Butter Shrimp','Shrimp (200g), Garlic (3 cloves, minced), Butter (3 tbsp), Lemon Juice (1 tbsp), Parsley (1 tbsp, chopped)','1. Heat butter and sautÃ© garlic.\r\n2. Add shrimp and cook until pink.\r\n3. Drizzle lemon juice and garnish with parsley.',15,'Easy','Seafood','https://www.youtube.com/watch?v=kzPAeP8flMk&pp=ygUUR2FybGljIEJ1dHRlciBTaHJpbXA%3D'),(31,'Falafel','Chickpeas (1 cup), Onion (1, chopped), Garlic (2 cloves, minced), Cumin (1 tsp), Coriander (1 tsp), Parsley (1/4 cup)','1. Blend all ingredients into a coarse mixture.\n2. Shape into balls and deep fry.\n3. Serve with hummus or pita.',30,'Medium','Middle Eastern','https://www.youtube.com/watch?v=HuQxpx8tJxM'),(32,'Chocolate Mousse','Dark Chocolate (200g), Heavy Cream (1 cup), Sugar (2 tbsp), Egg Whites (2)','1. Melt chocolate and cool slightly.\r\n2. Whip egg whites until stiff.\r\n3. Fold in whipped cream and chill.',20,'Medium','Dessert','https://www.youtube.com/watch?v=3eXycW1fZEI&ab_channel=Tastemade'),(33,'Beef Tacos','Ground Beef (300g), Tortillas (4), Onion (1, chopped), Tomatoes (1, diced), Lettuce (1/2 cup, shredded), Cheese (1/2 cup)','1. Cook beef with onions and spices.\n2. Fill tortillas with beef and toppings.\n3. Serve with salsa.',25,'Easy','Mexican','https://www.youtube.com/watch?v=HuvnU1dE8S8'),(34,'Pumpkin Soup','Pumpkin (2 cups, cubed), Onion (1, chopped), Garlic (2 cloves, minced), Vegetable Broth (2 cups), Cream (1/2 cup)','1. SautÃ© onions and garlic.\n2. Add pumpkin and broth, cook until soft.\n3. Blend and add cream before serving.',30,'Easy','Soup','https://www.youtube.com/watch?v=QuW8-8L4RUg'),(35,'Spaghetti Carbonara','Spaghetti (200g), Bacon (100g, chopped), Eggs (2), Parmesan Cheese (1/2 cup), Black Pepper (1 tsp)','1. Cook spaghetti and drain.\n2. SautÃ© bacon until crispy.\n3. Mix eggs, cheese, and pepper.\n4. Toss with hot pasta and bacon.',20,'Medium','Italian','https://www.youtube.com/watch?v=OWKEDQ5sA3g'),(36,'Clam Chowder','Clams (200g), Potatoes (1 cup, diced), Onion (1, chopped), Celery (1/2 cup, chopped), Heavy Cream (1/2 cup), Butter (2 tbsp)','1. SautÃ© onions and celery in butter.\n2. Add potatoes, clams, and broth.\n3. Simmer and stir in cream.',40,'Medium','Seafood','https://www.youtube.com/watch?v=kM0EWKVG7sA'),(37,'Gnocchi with Pesto','Gnocchi (200g), Basil (1 cup), Garlic (1 clove), Parmesan Cheese (1/2 cup), Olive Oil (3 tbsp), Pine Nuts (2 tbsp)','1. Blend basil, garlic, cheese, and nuts with oil.\n2. Cook gnocchi in boiling water.\n3. Toss with pesto and serve.',25,'Medium','Italian','https://www.youtube.com/watch?v=3F2IXNVxf4c'),(38,'Korean Bibimbap','Rice (2 cups), Carrots (1/2 cup, julienned), Spinach (1/2 cup), Mushrooms (1/2 cup, sliced), Egg (1), Gochujang Sauce (2 tbsp)','1. Cook rice and set aside.\n2. SautÃ© vegetables and arrange over rice.\n3. Top with fried egg and gochujang sauce.',30,'Medium','Korean','https://www.youtube.com/watch?v=it06GvfjP8E'),(39,'Margarita Pizza','Pizza Dough (1), Tomato Sauce (1/2 cup), Mozzarella (1 cup), Basil Leaves (1/4 cup), Olive Oil (2 tbsp)','1. Spread sauce over dough.\n2. Add mozzarella and basil.\n3. Bake at 200Â°C for 15 minutes.',20,'Easy','Italian','https://www.youtube.com/watch?v=Qv96yJYhk3M'),(40,'Banana Bread','Bananas (2, mashed), Flour (1.5 cups), Sugar (3/4 cup), Eggs (2), Butter (1/2 cup, melted), Baking Powder (1 tsp)','1. Mix all ingredients.\n2. Pour batter into a greased loaf pan.\n3. Bake at 180Â°C for 50 minutes.',60,'Easy','Dessert','https://www.youtube.com/watch?v=6Lz2OKd9ITc'),(41,'Tandoori Chicken','Chicken (500g), Yogurt (1/2 cup), Garlic (3 cloves, minced), Ginger (1 tbsp, grated), Tandoori Masala (2 tbsp), Lemon Juice (1 tbsp)','1. Marinate chicken with all ingredients for 4 hours.\n2. Grill or bake at 200Â°C for 30 minutes.\n3. Serve with mint chutney.',45,'Medium','Indian','https://www.youtube.com/watch?v=3Nbd64v0h7o'),(42,'Shakshuka','Tomatoes (4, diced), Eggs (3), Onion (1, chopped), Garlic (2 cloves, minced), Bell Pepper (1, chopped), Cumin (1 tsp)','1. SautÃ© onion, garlic, and bell pepper.\n2. Add tomatoes and simmer for 10 minutes.\n3. Crack eggs over mixture, cover, and cook until eggs set.',30,'Easy','Middle Eastern','https://www.youtube.com/watch?v=uJZGRxpTR3U'),(43,'Mushroom Risotto','Arborio Rice (1.5 cups), Mushrooms (1 cup, sliced), Onion (1, chopped), Garlic (2 cloves, minced), Parmesan Cheese (1/2 cup), White Wine (1/2 cup)','1. SautÃ© onions, garlic, and mushrooms.\n2. Add rice and toast for a minute.\n3. Add wine and stir until absorbed.\n4. Gradually add broth and stir until creamy.',40,'Medium','Italian','https://www.youtube.com/watch?v=DrkCRYF_V1Y'),(44,'Butter Chicken','Chicken (500g), Tomato Puree (1 cup), Cream (1/2 cup), Butter (2 tbsp), Garlic (3 cloves, minced), Garam Masala (1 tbsp)','1. Marinate chicken with spices and yogurt for 2 hours.\n2. Cook in butter, then add tomato puree and simmer.\n3. Stir in cream and serve.',50,'Medium','Indian','https://www.youtube.com/watch?v=FT_Mp8ilXUo'),(45,'Egg Fried Rice','Rice (2 cups, cooked), Eggs (2, beaten), Soy Sauce (2 tbsp), Green Onions (1/4 cup, chopped), Carrots (1/2 cup, diced), Peas (1/2 cup)','1. Heat oil in a pan and scramble eggs.\n2. Add vegetables and stir-fry for 2 minutes.\n3. Add rice and soy sauce, mix well.',20,'Easy','Chinese','https://www.youtube.com/watch?v=2jT5auU2vOQ'),(46,'BBQ Ribs','Pork Ribs (500g), BBQ Sauce (1/2 cup), Garlic Powder (1 tsp), Paprika (1 tsp), Salt (1 tsp), Black Pepper (1/2 tsp)','1. Season ribs with spices and bake at 150Â°C for 2 hours.\n2. Brush with BBQ sauce and broil for 5 minutes.',120,'Hard','American','https://www.youtube.com/watch?v=QAl5nK7tnPA'),(47,'Greek Salad','Cucumber (1, diced), Tomatoes (2, diced), Feta Cheese (1/2 cup, crumbled), Red Onion (1/4 cup, sliced), Olive Oil (2 tbsp), Oregano (1 tsp)','1. Combine all ingredients in a bowl.\n2. Drizzle with olive oil and sprinkle oregano.',10,'Easy','Salad','https://www.youtube.com/watch?v=B9PZXB7cRbc'),(48,'Shepherd?s Pie','Ground Lamb (500g), Potatoes (3, mashed), Carrots (1/2 cup, diced), Peas (1/2 cup), Onion (1, chopped), Butter (2 tbsp)','1. Cook lamb with vegetables.\n2. Spread in a baking dish and top with mashed potatoes.\n3. Bake at 180Â°C for 30 minutes.',60,'Medium','British','https://www.youtube.com/watch?v=3aL0gDZtFbE'),(49,'Fish Tacos','White Fish (200g, grilled), Tortillas (4), Cabbage (1/2 cup, shredded), Lime Juice (1 tbsp), Sour Cream (2 tbsp), Cilantro (1 tbsp, chopped)','1. Cook fish and flake into pieces.\n2. Fill tortillas with fish, cabbage, and toppings.\n3. Serve with lime.',25,'Easy','Mexican','https://www.youtube.com/watch?v=4FO6HY_wiwA'),(50,'Lemon Tart','Flour (1.5 cups), Butter (1/2 cup), Sugar (1/4 cup), Lemon Juice (1/2 cup), Eggs (2), Heavy Cream (1/4 cup)','1. Make a dough with flour, butter, and sugar.\n2. Bake crust at 180Â°C for 10 minutes.\n3. Mix lemon juice, eggs, and cream.\n4. Pour filling into crust and bake for 20 minutes.',45,'Medium','Dessert','https://www.youtube.com/watch?v=g35rS3upvPQ'),(51,'Vada Pav','Potatoes (2), Green Chilies (2), Garlic (4 cloves), Gram Flour (1 cup), Turmeric (1 tsp), Pav (4), Tamarind Chutney (2 tbsp), Green Chutney (2 tbsp), Mustard Seeds (1 tsp), Curry Leaves (5)','1. Boil and mash potatoes.\r\n    2. SautÃ© mustard seeds, garlic, green chilies, and turmeric. Mix with mashed potatoes.\r\n    3. Make small balls and coat with gram flour batter.\r\n    4. Deep fry until golden brown.\r\n    5. Serve inside pav with chutneys.',30,'Easy','Indian','https://www.youtube.com/watch?v=r4saZD0J_gU&pp=ygUIVmFkYSBQYXY%3D'),(52,'Butter Chicken','Chicken (500g), Butter (3 tbsp), Tomato Puree (1 cup), Cream (Â½ cup), Garlic (4 cloves, minced), Garam Masala (1 tsp), Salt .','1. Marinate chicken with spices and yogurt, then grill.  \r\n2. Cook tomato puree with butter and garlic.  \r\n3. Add grilled chicken, cream, and simmer until thick.  \r\n4. Garnish with fresh coriander and serve with naan.',45,'Medium','Indian','https://www.youtube.com/watch?v=a03U45jFxOI&pp=ygUVYnV0dGVyIGNoaWNrZW4gcmVjaXBl'),(53,'Paneer Tikka','Paneer (250g), Yogurt (Â½ cup), Ginger-Garlic Paste (1 tbsp), Lemon Juice (1 tbsp), Bell Peppers (1 cup, diced), Spices (1 tsp each of turmeric, chili powder, garam masala)','1. Marinate paneer and vegetables in yogurt and spices.   2. Skewer and grill until slightly charred.   3. Serve hot with mint chutney.',35,'Easy','Indian','https://www.youtube.com/watch?v=c-oVDb-O2Q8&pp=ygUTcGFuZWVyIHRpa2thIHJlY2lwZQ%3D%3D'),(54,'Masala Dosa','Rice (2 cups), Urad Dal (1 cup), Potatoes (3, boiled & mashed), Mustard Seeds (1 tsp), Curry Leaves (5-6), Green Chilies (2, chopped)',' 1. Soak rice and dal, grind into batter, and ferment overnight.  \r\n2. Prepare potato filling with spices and mustard seeds.  \r\n3. Spread batter thinly on tawa, cook until crispy, and fill with potatoes.  \r\n4. Serve with chutney and sambar.',50,'Easy','Indian','https://www.youtube.com/watch?v=mDqkxZ3UVzc&pp=ygUKbWFzbGEgZG9zYQ%3D%3D'),(55,'Aloo Paratha','Wheat Flour (2 cups), Potatoes (3, boiled & mashed), Green Chilies (2, chopped), Ghee (2 tbsp), Spices (1 tsp each of salt, garam masala, ajwain)','1. Knead wheat flour into dough and rest for 30 minutes.  \r\n2. Mix mashed potatoes with spices and green chilies.  \r\n3. Stuff dough with filling, roll, and cook on tawa with ghee.  \r\n4. Serve with butter and curd.',35,'Easy','Indian','https://www.youtube.com/watch?v=j3pDXY9fqSo&pp=ygUTYWxvbyBwYXJhdGhhIHJlY2lwZQ%3D%3D'),(56,'Pani Puri','Semolina (1 cup), Potatoes (2, boiled & mashed), Chickpeas (Â½ cup, boiled), Mint Leaves (Â½ cup), Tamarind Paste (2 tbsp), Spices (1 tsp each of cumin, black salt)','1. Make puris with semolina and fry until crispy. \n    2. Prepare mint-tamarind water. \n    3. Fill puris with potatoes, chickpeas, and pour spicy water. \n    4. Serve immediately.',25,'Easy','Indian','https://www.youtube.com/watch?v=Fb0iM3z84ks'),(57,'Chole Bhature','Chickpeas (1 cup, soaked overnight), Flour (2 cups), Yogurt (Â½ cup), Onion (1, chopped), Tomato Puree (1 cup), Spices (1 tsp each of garam masala, turmeric)','1. Cook chickpeas with onion-tomato masala. \n    2. Knead dough with flour and yogurt, let rest. \n    3. Roll and deep-fry bhature. \n    4. Serve with pickles and onions.',50,'Medium','Indian','https://www.youtube.com/watch?v=4oySvlu-wnw'),(58,'Dhokla','Gram Flour (2 cups), Yogurt (Â½ cup), Green Chilies (2, chopped), Mustard Seeds (1 tsp), Eno Fruit Salt (1 tsp), Curry Leaves (5-6)','1. Mix gram flour, yogurt, and fruit salt. \n    2. Steam the batter for 15-20 minutes. \n    3. Temper with mustard seeds and curry leaves. \n    4. Cut into pieces and serve.',30,'Easy','Indian','https://www.youtube.com/watch?v=hm1l6FFoG8M'),(59,'Gulab Jamun','Khoya (2 cups), Flour (Â½ cup), Sugar (1.5 cups), Cardamom Powder (Â½ tsp), Ghee (for frying), Rose Water (1 tbsp)','1. Knead khoya with flour and shape into balls. \r\n    2. Deep-fry in ghee on low heat until golden brown. \r\n    3. Soak in sugar syrup with rose water. \r\n    4. Serve warm.',45,'Medium','Dessert','https://www.youtube.com/watch?v=QFvd7u_YjVk&ab_channel=YourFoodLab');
